    def _predict_candidate_pairs(self, features, candidates):
        # DEBUG: Batched candidate embeddings can make ModelView's matrix
        # multiplication broadcast across users. Score each history against
        # its own two candidates through the unchanged host interface.
        if features.ndim != 2:
            raise ValueError("Pair scoring requires B x D features")
        candidates = torch.as_tensor(
            candidates, dtype=torch.long, device=features.device
        )
        if tuple(candidates.shape) != (features.shape[0], 2):
            raise ValueError("Pair scoring requires B x 2 candidate IDs")
        if features.shape[0] == 0:
            return features.new_empty((0, 2))

        scores = []
        for row in range(features.shape[0]):
            result = self.model.predict_score(
                features[row : row + 1], candidates[row]
            )
            # DEBUG: A single history may return shape (2,) or (1, 2).
            # Normalize only a verified two-score result; never flatten a
            # cross-user score matrix into apparently valid observations.
            if not isinstance(result, torch.Tensor) or result.numel() != 2:
                raise ValueError(
                    "ModelView.predict_score must return exactly two scores "
                    "for one history and two candidate IDs"
                )
            scores.append(result.reshape(2))
        return torch.stack(scores, dim=0)

